/**
 * Generates the Managed Services (Databases + Realtime) types and operation
 * tables of the TypeScript and Go SDKs from the Dashboard's generated OpenAPI
 * document (`hubfly-dashboard/openapi.json`, written by `make generate` there).
 *
 *   bun run scripts/generate-managed.ts          # (re)write the generated files
 *   bun run scripts/generate-managed.ts --check  # exit 1 when they drift from the spec
 *
 * `OPENAPI_PATH` overrides the spec location (as for verify-spec-diff.ts).
 *
 * Outputs (never edit them by hand):
 *   packages/ts/src/modules/managed-types.ts  interfaces + MANAGED_OPERATIONS table
 *   packages/go/managed_types.go               structs + one unexported func per operation
 *
 * The hand-written modules (packages/ts/src/modules/managed*.ts,
 * packages/go/managed*.go) call operations only through these tables, so every
 * request and response type comes from the spec.
 */
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

export interface Schema {
  type?: string;
  properties?: Record<string, Schema>;
  required?: string[];
  additionalProperties?: boolean | Schema;
  items?: Schema;
  nullable?: boolean;
  enum?: Array<string | number | boolean>;
  const?: string | number | boolean;
  oneOf?: Schema[];
  anyOf?: Schema[];
  description?: string;
}

interface SpecOperation {
  operationId?: string;
  parameters?: Array<{ name: string; in: string; required?: boolean; schema?: Schema }>;
  requestBody?: { required?: boolean; content?: Record<string, { schema?: Schema }> };
  responses?: Record<string, { content?: Record<string, { schema?: Schema }> }>;
}

export interface OpenApiSpec {
  paths?: Record<string, Record<string, SpecOperation>>;
}

export const GENERATED_MARKER = 'Code generated by scripts/generate-managed.ts. DO NOT EDIT.';

const ROOT = path.resolve(import.meta.dirname, '..');
export const TS_OUT = path.join(ROOT, 'packages/ts/src/modules/managed-types.ts');
export const GO_OUT = path.join(ROOT, 'packages/go/managed_types.go');

/** Operations of the Managed Services API: every path with a `/managed` segment. */
export function isManagedPath(routePath: string): boolean {
  return /\/managed(\/|$)/.test(routePath);
}

export function resolveOpenApiSpecPath(): string {
  if (process.env.OPENAPI_PATH) return process.env.OPENAPI_PATH;
  const defaultPath = path.resolve(import.meta.dirname, '../../hubfly-dashboard/openapi.json');
  if (fs.existsSync(defaultPath)) return defaultPath;
  const cwdPath = path.resolve(process.cwd(), '../hubfly-dashboard/openapi.json');
  if (fs.existsSync(cwdPath)) return cwdPath;
  throw new Error(`OpenAPI spec not found at ${defaultPath} or ${cwdPath}. Set OPENAPI_PATH.`);
}

// ---------------------------------------------------------------------------
// Names: entity names for shapes that appear in many responses. Keys are the
// names the generator derives (operation + property path); every identical
// shape shares the chosen name. Unlisted shapes keep their derived name.
// ---------------------------------------------------------------------------

