// ---------------------------------------------------------------------------
// Operations
// ---------------------------------------------------------------------------

type Prim = 'string' | 'number' | 'boolean';
type Role = 'req' | 'res';

interface QueryParam {
  name: string;
  required: boolean;
  schema: Schema;
}

export interface ManagedOperation {
  id: string;
  base: string;
  method: string;
  path: string;
  pathParams: string[];
  query: QueryParam[];
  body: Schema | null;
  bodyKind: 'none' | 'empty' | 'json';
  response: Schema | null;
}

function pascal(value: string): string {
  return value
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');
}

function hasProperties(schema: Schema | null | undefined): boolean {
  return !!schema && !!schema.properties && Object.keys(schema.properties).length > 0;
}

export function collectManagedOperations(spec: OpenApiSpec): ManagedOperation[] {
  const ops: ManagedOperation[] = [];
  for (const [routePath, methods] of Object.entries(spec.paths ?? {})) {
    if (!isManagedPath(routePath)) continue;
    for (const [method, details] of Object.entries(methods)) {
      const id = details.operationId;
      if (!id) throw new Error(`${method.toUpperCase()} ${routePath} has no operationId`);
      const pathParams = [...routePath.matchAll(/:([A-Za-z0-9_]+)/g)].map((match) => match[1]);
      const query = (details.parameters ?? [])
        .filter((param) => param.in === 'query')
        .map((param) => ({ name: param.name, required: !!param.required, schema: param.schema ?? { type: 'string' } }));
      const body = details.requestBody?.content?.['application/json']?.schema ?? null;
      const envelope = details.responses?.['200']?.content?.['application/json']?.schema;
      ops.push({
        id,
        base: id.charAt(0).toUpperCase() + id.slice(1),
        method: method.toUpperCase(),
        path: routePath,
        pathParams,
        query,
        body: hasProperties(body) ? body : null,
        bodyKind: !body ? 'none' : hasProperties(body) ? 'json' : 'empty',
        response: envelope?.properties?.data ?? null,
      });
    }
  }
  return ops.sort((a, b) => a.id.localeCompare(b.id));
}

// ---------------------------------------------------------------------------
// Type model
// ---------------------------------------------------------------------------

type TypeRef =
  | { kind: 'prim'; prim: Prim; nullable: boolean }
  | { kind: 'literal'; prim: Prim; values: Array<string | number | boolean>; nullable: boolean }
  | { kind: 'array'; item: TypeRef; nullable: boolean }
  | { kind: 'map'; value: TypeRef; nullable: boolean }
  | { kind: 'named'; name: string; nullable: boolean }
  | { kind: 'union'; members: TypeRef[]; nullable: boolean }
  | { kind: 'empty'; nullable: boolean }
  | { kind: 'unknown'; nullable: boolean };

interface Field {
  prop: string;
  type: TypeRef;
  required: boolean;
}

type Decl =
  | { kind: 'struct'; name: string; role: Role; fields: Field[]; doc: string }
  | { kind: 'variants'; name: string; role: Role; members: string[]; fields: Field[]; doc: string }
  | { kind: 'alias'; name: string; role: Role; target: TypeRef; doc: string };

function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  if (value && typeof value === 'object') {
    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([key]) => key !== 'description' && key !== 'title' && key !== 'example')
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    return `{${entries.map(([key, inner]) => `${JSON.stringify(key)}:${canonical(inner)}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

function singular(word: string): string {
  if (/ies$/.test(word)) return word.slice(0, -3) + 'y';
  if (/(ss|x|ch|sh)es$/.test(word)) return word.slice(0, -2);
  if (/[^s]s$/.test(word)) return word.slice(0, -1);
  return word + 'Item';
}

function isObjectSchema(schema: Schema): boolean {
  return schema.type === 'object' && hasProperties(schema);
}

function isVariantSchema(schema: Schema): boolean {
  return !!schema.oneOf && schema.oneOf.length > 0 && schema.oneOf.every(isObjectSchema);
}

function variantSuffix(variant: Schema, index: number): string {
  for (const inner of Object.values(variant.properties ?? {})) {
    if (inner.const !== undefined && typeof inner.const === 'string') return pascal(inner.const);
  }
  return `Variant${index + 1}`;
}

interface NameContext {
  stem: string;
  role: Role;
  /** Where the shape was first seen, for doc comments. */
  where: string;
}

function nameFor(ctx: NameContext): string {
  return ctx.role === 'req' ? `${ctx.stem}Input` : ctx.stem;
}

class Model {
  readonly decls = new Map<string, Decl>();
  private readonly candidates = new Map<string, string[]>();
  private readonly firstWhere = new Map<string, string>();
  private readonly chosen = new Map<string, string>();
  private readonly used = new Set<string>();

  constructor(private readonly ops: ManagedOperation[]) {}

  build(): void {
    // Pass 1: every object shape and the names the generator would give it.
    this.walkOperations((schema, ctx, rootName) => this.noteCandidate(schema, ctx, rootName));
    for (const op of this.ops) {
      this.used.add(`${op.base}Response`);
      this.used.add(`${op.base}Body`);
      this.used.add(`${op.base}Query`);
    }
    for (const [key, names] of this.candidates) {
      const override = names.find((name) => NAME_OVERRIDES[name]);
      let name = override ? NAME_OVERRIDES[override] : names[0];
      if (this.isRootName(name) && !override) {
        this.chosen.set(key, name);
        continue;
      }
      let unique = name;
      for (let n = 2; this.used.has(unique); n++) unique = `${name}${n}`;
      this.used.add(unique);
      this.chosen.set(key, unique);
    }
    // Pass 2: declarations.
    for (const op of this.ops) {
      const responseName = `${op.base}Response`;
      const responseDoc = `Data of ${op.method} ${op.path} (${op.id}).`;
      if (op.response) {
        const ref = this.typeOf(op.response, { stem: op.base, role: 'res', where: `${op.id} response` }, responseName);
        this.addRoot(responseName, 'res', ref, responseDoc);
      } else {
        this.decls.set(responseName, { kind: 'alias', name: responseName, role: 'res', target: { kind: 'unknown', nullable: false }, doc: responseDoc });
      }
      if (op.body) {
        const bodyName = `${op.base}Body`;
        const ref = this.typeOf(op.body, { stem: op.base, role: 'req', where: `${op.id} body` }, bodyName);
        this.addRoot(bodyName, 'req', ref, `Request body of ${op.method} ${op.path} (${op.id}).`);
      }
    }
  }

  private isRootName(name: string): boolean {
    return /(Response|Body)$/.test(name) && this.ops.some((op) => name === `${op.base}Response` || name === `${op.base}Body`);
  }

  private walkOperations(visit: (schema: Schema, ctx: NameContext, rootName: string | null) => void): void {
    for (const op of this.ops) {
      if (op.response) this.walk(op.response, { stem: op.base, role: 'res', where: `${op.id} response` }, `${op.base}Response`, visit);
      if (op.body) this.walk(op.body, { stem: op.base, role: 'req', where: `${op.id} body` }, `${op.base}Body`, visit);
    }
  }

  private walk(schema: Schema, ctx: NameContext, rootName: string | null, visit: (schema: Schema, ctx: NameContext, rootName: string | null) => void): void {
    if (isObjectSchema(schema) || isVariantSchema(schema)) visit(schema, ctx, rootName);
    if (isVariantSchema(schema)) {
      schema.oneOf!.forEach((variant, index) =>
        this.walk(variant, { ...ctx, stem: ctx.stem + variantSuffix(variant, index), where: ctx.where }, null, visit),
      );
      return;
    }
    for (const [prop, inner] of Object.entries(schema.properties ?? {})) {
      this.walkChild(inner, prop, ctx, visit);
    }
    if (schema.type === 'array' && schema.items) this.walkChild(schema.items, 'item', ctx, visit);
    if (schema.oneOf) schema.oneOf.forEach((inner) => this.walkChild(inner, 'value', ctx, visit));
  }

  private walkChild(schema: Schema, prop: string, ctx: NameContext, visit: (schema: Schema, ctx: NameContext, rootName: string | null) => void): void {
    const child = this.childContext(schema, prop, ctx);
    this.walk(child.schema, child.ctx, null, visit);
  }

  /** Unwraps arrays and maps so `items: [{…}]` names the element `<Stem>Item`. */
  private childContext(schema: Schema, prop: string, ctx: NameContext): { schema: Schema; ctx: NameContext } {
    const where = `${ctx.where}.${prop}`;
    if (schema.type === 'array' && schema.items) {
      return this.childContext(schema.items, singular(prop), { ...ctx, where });
    }
    if (schema.type === 'object' && !hasProperties(schema) && typeof schema.additionalProperties === 'object') {
      return this.childContext(schema.additionalProperties, `${prop}Value`, { ...ctx, where });
    }
    return { schema, ctx: { stem: ctx.stem + pascal(prop), role: ctx.role, where } };
  }

  private keyOf(schema: Schema, role: Role): string {
    return `${role}|${canonical(schema)}`;
  }

  private noteCandidate(schema: Schema, ctx: NameContext, rootName: string | null): void {
    const key = this.keyOf(schema, ctx.role);
    const list = this.candidates.get(key) ?? [];
    list.push(rootName ?? nameFor(ctx));
    this.candidates.set(key, list);
    if (!this.firstWhere.has(key)) this.firstWhere.set(key, ctx.where);
  }

  private addRoot(name: string, role: Role, ref: TypeRef, doc: string): void {
    if (ref.kind === 'named' && ref.name === name && !ref.nullable) return; // the struct itself
    this.decls.set(name, { kind: 'alias', name, role, target: ref, doc });
  }

  private typeOf(schema: Schema, ctx: NameContext, rootName: string | null = null): TypeRef {
    const nullable = !!schema.nullable;
    if (isVariantSchema(schema)) {
      const name = this.chosen.get(this.keyOf(schema, ctx.role))!;
      if (!this.decls.has(name)) {
        const members = schema.oneOf!.map((variant, index) => {
          const ref = this.typeOf(variant, { ...ctx, stem: ctx.stem + variantSuffix(variant, index) });
          if (ref.kind !== 'named') throw new Error('variant is not an object');
          return ref.name;
        });
        const merged = new Map<string, Field>();
        schema.oneOf!.forEach((variant, index) => {
          for (const field of this.fieldsOf(variant, { ...ctx, stem: ctx.stem + variantSuffix(variant, index) })) {
            const inAll = schema.oneOf!.every((other) => (other.required ?? []).includes(field.prop));
            const existing = merged.get(field.prop);
            if (!existing) {
              merged.set(field.prop, { ...field, required: inAll, type: field.type.kind === 'literal' ? { kind: 'prim', prim: field.type.prim, nullable: field.type.nullable } : field.type });
            }
          }
        });
        this.decls.set(name, {
          kind: 'variants',
          name,
          role: ctx.role,
          members,
          fields: [...merged.values()],
          doc: `One of ${members.join(', ')} (first seen in ${this.firstWhere.get(this.keyOf(schema, ctx.role))}).`,
        });
      }
      return { kind: 'named', name, nullable };
    }
    if (schema.oneOf) {
      const members = schema.oneOf.map((inner) => this.typeOf(inner, ctx));
      if (members.every((m) => m.kind === 'literal' || m.kind === 'prim')) {
        const prims = new Set(members.map((m) => (m as { prim: Prim }).prim));
        if (prims.size === 1) {
          const prim = [...prims][0];
          if (members.every((m) => m.kind === 'literal')) {
            const values = members.flatMap((m) => (m as { values: Array<string | number | boolean> }).values);
            if (prim === 'boolean' && values.includes(true) && values.includes(false)) return { kind: 'prim', prim, nullable };
            return { kind: 'literal', prim, values, nullable };
          }
          return { kind: 'prim', prim, nullable };
        }
      }
      return { kind: 'union', members, nullable };
    }
    if (schema.const !== undefined) {
      return { kind: 'literal', prim: primOf(schema), values: [schema.const], nullable };
    }
    if (schema.enum) {
      return { kind: 'literal', prim: primOf(schema), values: schema.enum, nullable };
    }
    switch (schema.type) {
      case 'string':
      case 'number':
      case 'boolean':
        return { kind: 'prim', prim: schema.type, nullable };
      case 'integer':
        return { kind: 'prim', prim: 'number', nullable };
      case 'array': {
        const child = this.childContext(schema.items ?? {}, 'item', ctx);
        return { kind: 'array', item: schema.items ? this.typeOf(schema.items, { ...child.ctx, stem: ctx.stem + 'Item' }) : { kind: 'unknown', nullable: false }, nullable };
      }
      case 'object': {
        if (hasProperties(schema)) {
          const key = this.keyOf(schema, ctx.role);
          const name = this.chosen.get(key) ?? rootName ?? nameFor(ctx);
          if (!this.decls.has(name)) {
            this.decls.set(name, { kind: 'struct', name, role: ctx.role, fields: [], doc: '' });
            const fields = this.fieldsOf(schema, ctx);
            const where = this.firstWhere.get(key) ?? ctx.where;
            this.decls.set(name, { kind: 'struct', name, role: ctx.role, fields, doc: where });
          }
          return { kind: 'named', name, nullable };
        }
        if (typeof schema.additionalProperties === 'object') {
          return { kind: 'map', value: this.typeOf(schema.additionalProperties, { ...ctx, stem: ctx.stem + 'Value' }), nullable };
        }
        return { kind: 'empty', nullable };
      }
      default:
        return { kind: 'unknown', nullable };
    }
  }

  private fieldsOf(schema: Schema, ctx: NameContext): Field[] {
    const required = new Set(schema.required ?? []);
    return Object.entries(schema.properties ?? {}).map(([prop, inner]) => ({
      prop,
      type: this.typeOfChild(inner, prop, ctx),
      required: required.has(prop),
    }));
  }

  /** Like typeOf, but names array elements / map values after the property. */
  private typeOfChild(schema: Schema, prop: string, ctx: NameContext): TypeRef {
    const where = `${ctx.where}.${prop}`;
    if (schema.type === 'array' && schema.items) {
      const inner = this.typeOfChild(schema.items, singular(prop), { ...ctx, where });
      return { kind: 'array', item: inner, nullable: !!schema.nullable };
    }
    if (schema.type === 'object' && !hasProperties(schema) && typeof schema.additionalProperties === 'object') {
      const inner = this.typeOfChild(schema.additionalProperties, `${prop}Value`, { ...ctx, where });
      return { kind: 'map', value: inner, nullable: !!schema.nullable };
    }
    return this.typeOf(schema, { stem: ctx.stem + pascal(prop), role: ctx.role, where });
  }
}

function primOf(schema: Schema): Prim {
  if (schema.type === 'number' || schema.type === 'integer') return 'number';
  if (schema.type === 'boolean') return 'boolean';
  if (schema.type === 'string') return 'string';
  const sample = schema.const ?? schema.enum?.[0];
  return typeof sample === 'number' ? 'number' : typeof sample === 'boolean' ? 'boolean' : 'string';
}

// ---------------------------------------------------------------------------
// TypeScript
// ---------------------------------------------------------------------------

function tsLiteral(value: string | number | boolean): string {
  return typeof value === 'string' ? JSON.stringify(value) : String(value);
}

function tsType(ref: TypeRef): string {
  let text: string;
  switch (ref.kind) {
    case 'prim':
      text = ref.prim;
      break;
    case 'literal':
      text = ref.values.map(tsLiteral).join(' | ');
      break;
    case 'array': {
      const inner = tsType(ref.item);
      text = /[|&]/.test(inner) ? `Array<${inner}>` : `${inner}[]`;
      break;
    }
    case 'map':
      text = `Record<string, ${tsType(ref.value)}>`;
      break;
    case 'named':
      text = ref.name;
      break;
    case 'union': {
      const members = new Set(ref.members.flatMap((member) => tsType(member).split(' | ')));
      if (members.has('true') && members.has('false')) {
        members.delete('true');
        members.delete('false');
        members.add('boolean');
      }
      text = [...members].join(' | ');
      break;
    }
    case 'empty':
      text = 'Record<string, never>';
      break;
    default:
      text = 'unknown';
  }
  return ref.nullable && ref.kind !== 'unknown' ? `${text} | null` : text;
}

function tsKey(prop: string): string {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(prop) ? prop : JSON.stringify(prop);
}

function tsQueryType(schema: Schema): string {
  if (schema.enum) return schema.enum.map(tsLiteral).join(' | ');
  if (schema.type === 'number' || schema.type === 'integer') return 'number';
  if (schema.type === 'boolean') return 'boolean';
  return 'string';
}

export function renderTypeScript(ops: ManagedOperation[], model: Model): string {
  const out: string[] = [];
  out.push(`// ${GENERATED_MARKER}`);
  out.push('// Source: hubfly-dashboard/openapi.json (Managed Services API). Run `make generate-managed`.');
  out.push('');
  const decls = [...model.decls.values()].sort((a, b) => a.name.localeCompare(b.name));
  for (const decl of decls) {
    if (decl.kind === 'struct') {
      out.push(`/** ${decl.role === 'req' ? 'Request object' : 'Object'} (first seen in ${decl.doc}). */`);
      out.push(`export interface ${decl.name} {`);
      for (const field of decl.fields) {
        out.push(`  ${tsKey(field.prop)}${field.required ? '' : '?'}: ${tsType(field.type)};`);
      }
      out.push('}');
    } else if (decl.kind === 'variants') {
      out.push(`/** ${decl.doc} */`);
      out.push(`export type ${decl.name} = ${decl.members.join(' | ')};`);
    } else {
      out.push(`/** ${decl.doc} */`);
      out.push(`export type ${decl.name} = ${tsType(decl.target)};`);
    }
    out.push('');
  }
  for (const op of ops) {
    if (op.query.length === 0) continue;
    out.push(`/** Query of ${op.method} ${op.path} (${op.id}). */`);
    out.push(`export interface ${op.base}Query {`);
    for (const param of op.query) {
      out.push(`  ${tsKey(param.name)}${param.required ? '' : '?'}: ${tsQueryType(param.schema)};`);
    }
    out.push('}');
    out.push('');
  }
  out.push('/** Every Managed Services operation: method, path template, path parameters, query names and body kind. */');
  out.push('export const MANAGED_OPERATIONS = {');
  for (const op of ops) {
    out.push(
      `  ${op.id}: { method: ${JSON.stringify(op.method)}, path: ${JSON.stringify(op.path)}, pathParams: [${op.pathParams.map((p) => JSON.stringify(p)).join(', ')}], query: [${op.query.map((q) => JSON.stringify(q.name)).join(', ')}], body: ${JSON.stringify(op.bodyKind)} },`,
    );
  }
  out.push('} as const;');
  out.push('');
  out.push('export type ManagedOperationId = keyof typeof MANAGED_OPERATIONS;');
  out.push('');
  out.push('/** Path parameters, query, body and response data of each operation. */');
  out.push('export interface ManagedOperationTypes {');
  for (const op of ops) {
    const params = op.pathParams.length ? `{ ${op.pathParams.map((p) => `${p}: string`).join('; ')} }` : 'Record<string, never>';
    const query = op.query.length ? `${op.base}Query` : 'undefined';
    const body = op.bodyKind === 'json' ? `${op.base}Body` : 'undefined';
    out.push(`  ${op.id}: { params: ${params}; query: ${query}; body: ${body}; response: ${op.base}Response };`);
  }
  out.push('}');
  out.push('');
  return out.join('\n');
}

// ---------------------------------------------------------------------------
// Go
// ---------------------------------------------------------------------------

const GO_INITIALISMS = new Set(['e2e', 'id', 'ids', 'url', 'urls', 'ip', 'ips', 'api', 'http', 'https', 'tls', 'sql', 'cpu', 'json', 'ttl', 'cidr', 'uuid', 'uri', 'jwt', 'pem', 'dns', 'ssl']);

export function goName(value: string): string {
  const words = value
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean);
  return words
    .map((word) => {
      const lower = word.toLowerCase();
      if (GO_INITIALISMS.has(lower)) return lower === 'ids' ? 'IDs' : lower === 'urls' ? 'URLs' : lower === 'ips' ? 'IPs' : lower.toUpperCase();
      return word.charAt(0).toUpperCase() + word.slice(1);
    })
    .join('');
}

function goParamName(value: string): string {
  // projectId -> projectID, instanceId -> instanceID, databaseName -> databaseName
  const name = goName(value);
  const ident = name.charAt(0).toLowerCase() + name.slice(1);
  return ident === 'type' ? 'typ' : ident;
}

function goBase(ref: TypeRef): string {
  switch (ref.kind) {
    case 'prim':
    case 'literal':
      return ref.prim === 'string' ? 'string' : ref.prim === 'number' ? 'float64' : 'bool';
    case 'array':
      return `[]${goElem(ref.item)}`;
    case 'map':
      return `map[string]${goElem(ref.value)}`;
    case 'named':
      return ref.name;
    case 'empty':
      return 'struct{}';
    default:
      return 'any';
  }
}

function pointerable(ref: TypeRef): boolean {
  return ref.kind === 'prim' || ref.kind === 'literal' || ref.kind === 'named' || ref.kind === 'empty';
}

function goElem(ref: TypeRef): string {
  return ref.nullable && pointerable(ref) ? `*${goBase(ref)}` : goBase(ref);
}

function goFieldType(field: Field, role: Role): string {
  const base = goBase(field.type);
  if (!pointerable(field.type)) return base;
  if (field.type.nullable) return `*${base}`;
  if (field.required) return base;
  if (field.type.kind === 'named' || field.type.kind === 'empty') return `*${base}`;
  if (role === 'req' && (field.type.kind === 'prim' || field.type.kind === 'literal') && field.type.prim !== 'string') return `*${base}`;
  return base;
}

function goComment(field: Field): string {
  if (field.type.kind === 'literal') {
    const values = field.type.values.map((value) => (typeof value === 'string' ? JSON.stringify(value) : String(value)));
    return values.length === 1 ? ` // Always ${values[0]}.` : ` // One of ${values.join(', ')}.`;
  }
  return '';
}

function goStruct(name: string, fields: Field[], role: Role, doc: string): string[] {
  const out: string[] = [];
  out.push(`// ${name} ${doc}`);
  out.push(`type ${name} struct {`);
  for (const field of fields) {
    const tag = field.required ? field.prop : `${field.prop},omitempty`;
    out.push(`\t${goName(field.prop)} ${goFieldType(field, role)} \`json:"${tag}"\`${goComment(field)}`);
  }
  out.push('}');
  if (role === 'req') {
    out.push('');
    out.push(`// MarshalJSON omits unset optional fields and keeps empty, non-nil slices and maps.`);
    out.push(`func (v ${name}) MarshalJSON() ([]byte, error) {`);
    out.push(`\tm := make(map[string]any, ${fields.length})`);
    for (const field of fields) {
      const goField = `v.${goName(field.prop)}`;
      const type = goFieldType(field, role);
      const key = JSON.stringify(field.prop);
      if (field.required) {
        if (type.startsWith('[]') || type.startsWith('map[')) {
          out.push(`\tif ${goField} == nil {`);
          out.push(`\t\tm[${key}] = ${type}{}`);
          out.push('\t} else {');
          out.push(`\t\tm[${key}] = ${goField}`);
          out.push('\t}');
        } else {
          out.push(`\tm[${key}] = ${goField}`);
        }
      } else if (type.startsWith('*') || type.startsWith('[]') || type.startsWith('map[') || type === 'any') {
        out.push(`\tif ${goField} != nil {`);
        out.push(`\t\tm[${key}] = ${goField}`);
        out.push('\t}');
      } else if (type === 'string') {
        out.push(`\tif ${goField} != "" {`);
        out.push(`\t\tm[${key}] = ${goField}`);
        out.push('\t}');
      } else {
        out.push(`\tm[${key}] = ${goField}`);
      }
    }
    out.push('\treturn json.Marshal(m)');
    out.push('}');
  }
  return out;
}

function goQueryType(param: QueryParam): string {
  const schema = param.schema;
  const base = schema.type === 'number' || schema.type === 'integer' ? 'float64' : schema.type === 'boolean' ? 'bool' : 'string';
  return !param.required && base !== 'string' ? `*${base}` : base;
}

export function renderGo(ops: ManagedOperation[], model: Model): string {
  const out: string[] = [];
  out.push(`// ${GENERATED_MARKER}`);
  out.push('// Source: hubfly-dashboard/openapi.json (Managed Services API). Run `make generate-managed`.');
  out.push('');
  out.push('package hubfly');
  out.push('');
  out.push('import (');
  out.push('\t"context"');
  out.push('\t"encoding/json"');
  out.push('\t"net/url"');
  out.push(')');
  out.push('');
  const decls = [...model.decls.values()].sort((a, b) => a.name.localeCompare(b.name));
  for (const decl of decls) {
    if (decl.kind === 'struct') {
      out.push(...goStruct(decl.name, decl.fields, decl.role, `is an object of the Managed API (first seen in ${decl.doc}).`));
    } else if (decl.kind === 'variants') {
      out.push(...goStruct(decl.name, decl.fields, decl.role, `merges the variants ${decl.members.join(', ')}; fields of other variants are empty.`));
    } else {
      out.push(`// ${decl.name} is the ${decl.doc.charAt(0).toLowerCase()}${decl.doc.slice(1)}`);
      out.push(`type ${decl.name} = ${goElem(decl.target)}`);
    }
    out.push('');
  }
  for (const op of ops) {
    if (op.query.length === 0) continue;
    const name = `${op.base}Query`;
    out.push(`// ${name} is the query of ${op.method} ${op.path} (${op.id}).`);
    out.push(`// Optional numbers and booleans are pointers: nil leaves the parameter out.`);
    out.push(`type ${name} struct {`);
    for (const param of op.query) {
      const values = param.schema.enum ? ` // One of ${param.schema.enum.map((v) => JSON.stringify(v)).join(', ')}.` : '';
      out.push(`\t${goName(param.name)} ${goQueryType(param)}${param.required ? ' // Required.' : values}`);
    }
    out.push('}');
    out.push('');
    out.push(`func (q *${name}) encode() string {`);
    out.push('\tif q == nil {');
    out.push('\t\treturn ""');
    out.push('\t}');
    out.push('\tv := url.Values{}');
    for (const param of op.query) {
      const field = `q.${goName(param.name)}`;
      const type = goQueryType(param);
      const key = JSON.stringify(param.name);
      if (type === 'string') {
        if (param.required) out.push(`\tv.Set(${key}, ${field})`);
        else {
          out.push(`\tif ${field} != "" {`);
          out.push(`\t\tv.Set(${key}, ${field})`);
          out.push('\t}');
        }
      } else if (type.startsWith('*')) {
        out.push(`\tif ${field} != nil {`);
        out.push(`\t\tv.Set(${key}, ${type === '*bool' ? `formatManagedBool(*${field})` : `formatManagedNumber(*${field})`})`);
        out.push('\t}');
      } else {
        out.push(`\tv.Set(${key}, ${type === 'bool' ? `formatManagedBool(${field})` : `formatManagedNumber(${field})`})`);
      }
    }
    out.push('\treturn encodeManagedQuery(v)');
    out.push('}');
    out.push('');
  }
  out.push('// managedOperation describes one Managed Services operation (tests use the table).');
  out.push('type managedOperation struct {');
  out.push('\tID     string');
  out.push('\tMethod string');
  out.push('\tPath   string');
  out.push('}');
  out.push('');
  out.push('// managedOperations lists every Managed Services operation of the spec.');
  out.push('var managedOperations = []managedOperation{');
  for (const op of ops) out.push(`\t{ID: ${JSON.stringify(op.id)}, Method: ${JSON.stringify(op.method)}, Path: ${JSON.stringify(op.path)}},`);
  out.push('}');
  out.push('');
  for (const op of ops) {
    const params = op.pathParams.map((p) => `${goParamName(p)} string`);
    const allOptional = op.query.every((q) => !q.required);
    if (op.query.length) params.push(`query ${allOptional ? '*' : ''}${op.base}Query`);
    if (op.bodyKind === 'json') params.push(`body ${op.base}Body`);
    const format = op.path.replace(/:[A-Za-z0-9_]+/g, '%s');
    const args = op.pathParams.map(goParamName);
    const resp = `${op.base}Response`;
    out.push(`// ${op.id} calls ${op.method} ${op.path}.`);
    out.push(`func ${op.id}(ctx context.Context, c *Client${params.length ? ', ' + params.join(', ') : ''}) (*Response[${resp}], error) {`);
    out.push(`\tpath := managedPath(${JSON.stringify(format)}${args.length ? ', ' + args.join(', ') : ''})`);
    if (op.query.length) out.push(`\tpath += ${allOptional ? 'query' : '(&query)'}.encode()`);
    const bodyArg = op.bodyKind === 'json' ? 'body' : op.bodyKind === 'empty' ? 'struct{}{}' : 'nil';
    out.push(`\treturn Request[${resp}](ctx, c, ${JSON.stringify(op.method)}, path, ${bodyArg})`);
    out.push('}');
    out.push('');
  }
  return out.join('\n');
}

function gofmt(source: string): string {
  const result = spawnSync('gofmt', [], { input: source, encoding: 'utf8' });
  if (result.error) throw new Error(`gofmt is required to generate Go code: ${result.error.message}`);
  if (result.status !== 0) throw new Error(`gofmt failed:\n${result.stderr}`);
  return result.stdout;
}

// ---------------------------------------------------------------------------
// Entry points
// ---------------------------------------------------------------------------

export interface GeneratedFiles {
  operations: ManagedOperation[];
  files: Array<{ path: string; content: string }>;
}

export function generateManaged(spec: OpenApiSpec): GeneratedFiles {
  const operations = collectManagedOperations(spec);
  const model = new Model(operations);
  model.build();
  return {
    operations,
    files: [
      { path: TS_OUT, content: renderTypeScript(operations, model) },
      { path: GO_OUT, content: gofmt(renderGo(operations, model)) },
    ],
  };
}

/** Files whose content differs from what the spec generates (empty when in sync). */
export function checkManaged(specPath = resolveOpenApiSpecPath()): string[] {
  const spec = JSON.parse(fs.readFileSync(specPath, 'utf8')) as OpenApiSpec;
  const { files } = generateManaged(spec);
  return files
    .filter((file) => !fs.existsSync(file.path) || fs.readFileSync(file.path, 'utf8') !== file.content)
    .map((file) => path.relative(ROOT, file.path));
}

if (import.meta.main) {
  const specPath = resolveOpenApiSpecPath();
  if (process.argv.includes('--check')) {
    const drift = checkManaged(specPath);
    if (drift.length) {
      console.error(`Managed SDK types drift from ${specPath}:\n  ${drift.join('\n  ')}\nRun: make generate-managed`);
      process.exit(1);
    }
    console.log(`Managed SDK types match ${specPath}.`);
  } else {
    const spec = JSON.parse(fs.readFileSync(specPath, 'utf8')) as OpenApiSpec;
    const { operations, files } = generateManaged(spec);
    for (const file of files) fs.writeFileSync(file.path, file.content);
    console.log(`Generated ${operations.length} managed operations from ${specPath}:`);
    for (const file of files) console.log(`  ${path.relative(ROOT, file.path)}`);
  }
}
